import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.DYAmjhAm.js";const p=JSON.parse('{"title":"Class: BreezeConfig","description":"","frontmatter":{},"headers":[],"relativePath":"api/classes/BreezeConfig.md","filePath":"api/classes/BreezeConfig.md","lastUpdated":null}'),n={name:"api/classes/BreezeConfig.md"};function i(c,e,s,d,h,l){return t(),r("div",null,[...e[0]||(e[0]=[o('<p><a href="./../">breeze-client</a> / BreezeConfig</p><h1 id="class-breezeconfig" tabindex="-1">Class: BreezeConfig <a class="header-anchor" href="#class-breezeconfig" aria-label="Permalink to &quot;Class: BreezeConfig&quot;">​</a></h1><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/c2b3af9ef81a2eff9727726e0c824a491581b343/src/config/config.ts#L130" target="_blank" rel="noreferrer">src/config/config.ts:130</a></p><p>Breeze&#39;s global configuration: the adapter registry, the <code>fetch</code> transport, and registries Breeze uses to find functions and objects by name when it deserializes metadata. The single instance is <a href="./../variables/config">config</a>.</p><p>To configure Breeze, use <a href="./../functions/configureBreeze">configureBreeze</a>. The adapter methods here (<code>registerAdapter</code>, <code>initializeAdapterInstance</code>, <code>getAdapterInstance</code> and the rest) are the 2.x API. They still work, and adapters&#39; own static <code>register()</code> methods use them, but an application does not normally need to call them.</p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to &quot;Constructors&quot;">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to &quot;Constructor&quot;">​</a></h3><blockquote><p><strong>new BreezeConfig</strong>(): <code>BreezeConfig</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/c2b3af9ef81a2eff9727726e0c824a491581b343/src/config/config.ts#L198" target="_blank" rel="noreferrer">src/config/config.ts:198</a></p><p>Creates a configuration with nothing registered. Breeze creates the one instance there is, <a href="./../variables/config">config</a>; applications do not create their own.</p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>BreezeConfig</code></p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><h3 id="fetch" tabindex="-1">fetch? <a class="header-anchor" href="#fetch" aria-label="Permalink to &quot;fetch?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>fetch?</strong>: <a href="./../type-aliases/BreezeFetch"><code>BreezeFetch</code></a></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/c2b3af9ef81a2eff9727726e0c824a491581b343/src/config/config.ts#L182" target="_blank" rel="noreferrer">src/config/config.ts:182</a></p><p>The function Breeze makes HTTP requests with, unless a (deprecated) ajax adapter is registered. Set it with <code>configureBreeze({ fetch })</code>. When unset, <code>globalThis.fetch</code>.</p><hr><h3 id="functionregistry" tabindex="-1">functionRegistry <a class="header-anchor" href="#functionregistry" aria-label="Permalink to &quot;functionRegistry&quot;">​</a></h3><blockquote><p><strong>functionRegistry</strong>: <code>Record</code>&lt;<code>string</code>, <code>Function</code>&gt; = <code>{}</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/c2b3af9ef81a2eff9727726e0c824a491581b343/src/config/config.ts#L136" target="_blank" rel="noreferrer">src/config/config.ts:136</a></p><p>Functions registered by name with <a href="#registerfunction">BreezeConfig.registerFunction</a>. Breeze looks up validator factories here, under <code>&quot;Validator.&quot; + name</code>, when it imports metadata. Applications do not normally need it; use <a href="./Validator#register">Validator.register</a> and <a href="./Validator#registerfactory">Validator.registerFactory</a>.</p><hr><h3 id="interfaceinitialized" tabindex="-1">interfaceInitialized <a class="header-anchor" href="#interfaceinitialized" aria-label="Permalink to &quot;interfaceInitialized&quot;">​</a></h3><blockquote><p><strong>interfaceInitialized</strong>: <a href="./BreezeEvent"><code>BreezeEvent</code></a>&lt;{ <code>instance</code>: <a href="./../interfaces/BaseAdapter"><code>BaseAdapter</code></a>; <code>interfaceName</code>: <code>string</code>; <code>isDefault</code>: <code>boolean</code>; }&gt;</p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/c2b3af9ef81a2eff9727726e0c824a491581b343/src/config/config.ts#L155" target="_blank" rel="noreferrer">src/config/config.ts:155</a></p><p>Published each time an adapter is initialized, with the interface name, the adapter instance and whether it became the default for its interface. Breeze uses it to let adapters that depend on each other recompose (see <a href="./../interfaces/BaseAdapter#checkforrecomposition">BaseAdapter.checkForRecomposition</a>); applications do not normally need it.</p><hr><h3 id="objectregistry" tabindex="-1">objectRegistry <a class="header-anchor" href="#objectregistry" aria-label="Permalink to &quot;objectRegistry&quot;">​</a></h3><blockquote><p><strong>objectRegistry</strong>: <code>Record</code>&lt;<code>string</code>, <code>any</code>&gt; = <code>{}</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/c2b3af9ef81a2eff9727726e0c824a491581b343/src/config/config.ts#L148" target="_blank" rel="noreferrer">src/config/config.ts:148</a></p><p>Named instances Breeze can find again by name, keyed <code>&quot;&lt;TypeName&gt;.&lt;name&gt;&quot;</code>: every <a href="./JsonResultsAdapter">JsonResultsAdapter</a>, <a href="./NamingConvention">NamingConvention</a> and <a href="./LocalQueryComparisonOptions">LocalQueryComparisonOptions</a> registers itself here when created. Breeze uses it to resolve the names in exported metadata and exported entities. Applications do not normally need it.</p><hr><h3 id="stringifypad" tabindex="-1">stringifyPad <a class="header-anchor" href="#stringifypad" aria-label="Permalink to &quot;stringifyPad&quot;">​</a></h3><blockquote><p><strong>stringifyPad</strong>: <code>string</code> = <code>&#39;&#39;</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/c2b3af9ef81a2eff9727726e0c824a491581b343/src/config/config.ts#L177" target="_blank" rel="noreferrer">src/config/config.ts:177</a></p><p>The indentation Breeze passes to <code>JSON.stringify</code> when it serializes exported entities (<code>EntityManager.exportEntities</code>) and exported metadata (<code>MetadataStore.exportMetadata</code>). The default, <code>&#39;&#39;</code>, produces compact JSON; set it to, say, <code>&#39; &#39;</code> for readable output.</p><hr><h3 id="typeregistry" tabindex="-1">typeRegistry <a class="header-anchor" href="#typeregistry" aria-label="Permalink to &quot;typeRegistry&quot;">​</a></h3><blockquote><p><strong>typeRegistry</strong>: <code>Record</code>&lt;<code>string</code>, <code>Function</code>&gt; = <code>{}</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/c2b3af9ef81a2eff9727726e0c824a491581b343/src/config/config.ts#L141" target="_blank" rel="noreferrer">src/config/config.ts:141</a></p><p>Constructors registered by name with <a href="#registertype">BreezeConfig.registerType</a>. Nothing in Breeze 3 reads it; applications do not normally need it.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="getadapter" tabindex="-1">getAdapter() <a class="header-anchor" href="#getadapter" aria-label="Permalink to &quot;getAdapter()&quot;">​</a></h3><blockquote><p><strong>getAdapter</strong>(<code>interfaceName</code>, <code>adapterName?</code>): <code>any</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/c2b3af9ef81a2eff9727726e0c824a491581b343/src/config/config.ts#L233" target="_blank" rel="noreferrer">src/config/config.ts:233</a></p><p>Returns the ctor function used to implement a specific interface with a specific adapter name.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="interfacename" tabindex="-1">interfaceName <a class="header-anchor" href="#interfacename" aria-label="Permalink to &quot;interfaceName&quot;">​</a></h5><p><a href="./../type-aliases/AdapterType"><code>AdapterType</code></a></p><p>{String} One of the following interface names: &quot;ajax&quot;, &quot;dataService&quot;, &quot;modelLibrary&quot;, &quot;uriBuilder&quot;</p><h5 id="adaptername" tabindex="-1">adapterName? <a class="header-anchor" href="#adaptername" aria-label="Permalink to &quot;adapterName?&quot;">​</a></h5><p><code>string</code></p><p>{String} The name of any previously registered adapter. If this parameter is omitted then this method returns the &quot;default&quot; adapter for this interface. If there is no default adapter, then a null is returned.</p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>any</code></p><p>Returns either a ctor function or null.</p><hr><h3 id="getadapterinstance" tabindex="-1">getAdapterInstance() <a class="header-anchor" href="#getadapterinstance" aria-label="Permalink to &quot;getAdapterInstance()&quot;">​</a></h3><blockquote><p><strong>getAdapterInstance</strong>&lt;<code>T</code>&gt;(<code>interfaceName</code>, <code>adapterName?</code>): <code>T</code> | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/c2b3af9ef81a2eff9727726e0c824a491581b343/src/config/config.ts#L280" target="_blank" rel="noreferrer">src/config/config.ts:280</a></p><p>Returns the adapter instance corresponding to the specified interface and adapter names.</p><h4 id="type-parameters" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters" aria-label="Permalink to &quot;Type Parameters&quot;">​</a></h4><h5 id="t" tabindex="-1">T <a class="header-anchor" href="#t" aria-label="Permalink to &quot;T&quot;">​</a></h5><p><code>T</code> <em>extends</em> <a href="./../interfaces/BaseAdapter"><code>BaseAdapter</code></a></p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="interfacename-1" tabindex="-1">interfaceName <a class="header-anchor" href="#interfacename-1" aria-label="Permalink to &quot;interfaceName&quot;">​</a></h5><p><a href="./../type-aliases/AdapterType"><code>AdapterType</code></a></p><p>{String} The name of the interface.</p><h5 id="adaptername-1" tabindex="-1">adapterName? <a class="header-anchor" href="#adaptername-1" aria-label="Permalink to &quot;adapterName?&quot;">​</a></h5><p><code>string</code></p><p>{String} - The name of a previously registered adapter. If this parameter is omitted then the default implementation of the specified interface is returned. If there is no defaultInstance of this interface, then the first registered instance of this interface is returned.</p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>T</code> | <code>undefined</code></p><hr><h3 id="getinterfacedef" tabindex="-1">getInterfaceDef() <a class="header-anchor" href="#getinterfacedef" aria-label="Permalink to &quot;getInterfaceDef()&quot;">​</a></h3><blockquote><p><strong>getInterfaceDef</strong>&lt;<code>T</code>&gt;(<code>interfaceName</code>): <code>InterfaceDef</code>&lt;<code>T</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/c2b3af9ef81a2eff9727726e0c824a491581b343/src/config/config.ts#L344" target="_blank" rel="noreferrer">src/config/config.ts:344</a></p><p>Returns the registry entry for one adapter interface, which holds its registered adapters and its default instance. The name is matched without regard to case. Used by the adapter registration methods; applications do not normally need it.</p><h4 id="type-parameters-1" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters-1" aria-label="Permalink to &quot;Type Parameters&quot;">​</a></h4><h5 id="t-1" tabindex="-1">T <a class="header-anchor" href="#t-1" aria-label="Permalink to &quot;T&quot;">​</a></h5><p><code>T</code> <em>extends</em> <a href="./../interfaces/BaseAdapter"><code>BaseAdapter</code></a></p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="interfacename-2" tabindex="-1">interfaceName <a class="header-anchor" href="#interfacename-2" aria-label="Permalink to &quot;interfaceName&quot;">​</a></h5><p><code>string</code></p><p><code>&#39;ajax&#39;</code>, <code>&#39;dataService&#39;</code>, <code>&#39;modelLibrary&#39;</code> or <code>&#39;uriBuilder&#39;</code>.</p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>InterfaceDef</code>&lt;<code>T</code>&gt;</p><h4 id="throws" tabindex="-1">Throws <a class="header-anchor" href="#throws" aria-label="Permalink to &quot;Throws&quot;">​</a></h4><p>if there is no interface with that name.</p><hr><h3 id="getregisteredfunction" tabindex="-1">getRegisteredFunction() <a class="header-anchor" href="#getregisteredfunction" aria-label="Permalink to &quot;getRegisteredFunction()&quot;">​</a></h3><blockquote><p><strong>getRegisteredFunction</strong>(<code>fnName</code>): <code>Function</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/c2b3af9ef81a2eff9727726e0c824a491581b343/src/config/config.ts#L333" target="_blank" rel="noreferrer">src/config/config.ts:333</a></p><p>Returns the function registered under the given name with <a href="#registerfunction">BreezeConfig.registerFunction</a>, or <code>undefined</code> if there is none. Validators are registered as <code>&quot;Validator.&quot; + name</code>, so <code>config.getRegisteredFunction(&#39;Validator.maxLength&#39;)</code> returns the <code>maxLength</code> factory.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="fnname" tabindex="-1">fnName <a class="header-anchor" href="#fnname" aria-label="Permalink to &quot;fnName&quot;">​</a></h5><p><code>string</code></p><p>The name the function was registered under.</p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>Function</code></p><hr><h3 id="initializeadapterinstance" tabindex="-1"><s>initializeAdapterInstance()</s> <a class="header-anchor" href="#initializeadapterinstance" aria-label="Permalink to &quot;~~initializeAdapterInstance()~~&quot;">​</a></h3><blockquote><p><strong>initializeAdapterInstance</strong>(<code>interfaceName</code>, <code>adapterName</code>, <code>isDefault?</code>): <a href="./../interfaces/BaseAdapter"><code>BaseAdapter</code></a></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/c2b3af9ef81a2eff9727726e0c824a491581b343/src/config/config.ts#L257" target="_blank" rel="noreferrer">src/config/config.ts:257</a></p><p>Initializes a single adapter implementation. Initialization means either newing a instance of the specified interface and then calling &quot;initialize&quot; on it or simply calling &quot;initialize&quot; on the instance if it already exists.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="interfacename-3" tabindex="-1">interfaceName <a class="header-anchor" href="#interfacename-3" aria-label="Permalink to &quot;interfaceName&quot;">​</a></h5><p><a href="./../type-aliases/AdapterType"><code>AdapterType</code></a></p><p>{String} The name of the interface to which the adapter to initialize belongs.</p><h5 id="adaptername-2" tabindex="-1">adapterName <a class="header-anchor" href="#adaptername-2" aria-label="Permalink to &quot;adapterName&quot;">​</a></h5><p><code>string</code></p><p>{String} - The name of a previously registered adapter to initialize.</p><h5 id="isdefault" tabindex="-1">isDefault? <a class="header-anchor" href="#isdefault" aria-label="Permalink to &quot;isDefault?&quot;">​</a></h5><p><code>boolean</code> = <code>true</code></p><p>{Boolean} - Whether to make this the default &quot;adapter&quot; for this interface.</p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><a href="./../interfaces/BaseAdapter"><code>BaseAdapter</code></a></p><h4 id="deprecated" tabindex="-1">Deprecated <a class="header-anchor" href="#deprecated" aria-label="Permalink to &quot;Deprecated&quot;">​</a></h4><p>For configuring an application, use <code>configureBreeze({ ajax: MyAdapter, ... })</code> instead: the adapter classes are passed directly, so a misspelled name is a compile error rather than a runtime one. An adapter&#39;s own static <code>register()</code> still calls this - that is how an adapter registers itself, and is not deprecated. Not scheduled for removal.</p><hr><h3 id="registeradapter" tabindex="-1"><s>registerAdapter()</s> <a class="header-anchor" href="#registeradapter" aria-label="Permalink to &quot;~~registerAdapter()~~&quot;">​</a></h3><blockquote><p><strong>registerAdapter</strong>&lt;<code>T</code>&gt;(<code>interfaceName</code>, <code>adapterCtor</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/c2b3af9ef81a2eff9727726e0c824a491581b343/src/config/config.ts#L213" target="_blank" rel="noreferrer">src/config/config.ts:213</a></p><p>Method use to register implementations of standard breeze interfaces. Calls to this method are usually made as the last step within an adapter implementation.</p><h4 id="type-parameters-2" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters-2" aria-label="Permalink to &quot;Type Parameters&quot;">​</a></h4><h5 id="t-2" tabindex="-1">T <a class="header-anchor" href="#t-2" aria-label="Permalink to &quot;T&quot;">​</a></h5><p><code>T</code> <em>extends</em> <a href="./../interfaces/BaseAdapter"><code>BaseAdapter</code></a></p><h4 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="interfacename-4" tabindex="-1">interfaceName <a class="header-anchor" href="#interfacename-4" aria-label="Permalink to &quot;interfaceName&quot;">​</a></h5><p><a href="./../type-aliases/AdapterType"><code>AdapterType</code></a></p><p>{String} - one of the following interface names: &quot;ajax&quot;, &quot;dataService&quot;, &quot;modelLibrary&quot;, &quot;uriBuilder&quot;</p><h5 id="adapterctor" tabindex="-1">adapterCtor <a class="header-anchor" href="#adapterctor" aria-label="Permalink to &quot;adapterCtor&quot;">​</a></h5><p><code>AdapterCtor</code>&lt;<code>T</code>&gt;</p><p>{Function} - an ctor function that returns an instance of the specified interface.</p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>void</code></p><h4 id="deprecated-1" tabindex="-1">Deprecated <a class="header-anchor" href="#deprecated-1" aria-label="Permalink to &quot;Deprecated&quot;">​</a></h4><p>For configuring an application, use <code>configureBreeze({ ajax: MyAdapter, ... })</code> instead: the adapter classes are passed directly, so a misspelled name is a compile error rather than a runtime one. An adapter&#39;s own static <code>register()</code> still calls this - that is how an adapter registers itself, and is not deprecated. Not scheduled for removal.</p><hr><h3 id="registerfunction" tabindex="-1">registerFunction() <a class="header-anchor" href="#registerfunction" aria-label="Permalink to &quot;registerFunction()&quot;">​</a></h3><blockquote><p><strong>registerFunction</strong>(<code>fn</code>, <code>fnName</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/c2b3af9ef81a2eff9727726e0c824a491581b343/src/config/config.ts#L302" target="_blank" rel="noreferrer">src/config/config.ts:302</a></p><p>this is needed for reflection purposes when deserializing an object that needs a fn or ctor. Used to register validators.</p><h4 id="parameters-6" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-6" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="fn" tabindex="-1">fn <a class="header-anchor" href="#fn" aria-label="Permalink to &quot;fn&quot;">​</a></h5><p><code>Function</code></p><h5 id="fnname-1" tabindex="-1">fnName <a class="header-anchor" href="#fnname-1" aria-label="Permalink to &quot;fnName&quot;">​</a></h5><p><code>string</code></p><h4 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>void</code></p><hr><h3 id="registertype" tabindex="-1">registerType() <a class="header-anchor" href="#registertype" aria-label="Permalink to &quot;registerType()&quot;">​</a></h3><blockquote><p><strong>registerType</strong>(<code>ctor</code>, <code>typeName</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/c2b3af9ef81a2eff9727726e0c824a491581b343/src/config/config.ts#L318" target="_blank" rel="noreferrer">src/config/config.ts:318</a></p><p>Registers a constructor under a type name: stamps the name on its prototype as <code>_$typeName</code> and adds it to <a href="#typeregistry">BreezeConfig.typeRegistry</a>. Breeze registers <code>KeyGenerator</code> this way; applications do not normally need it.</p><h4 id="parameters-7" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-7" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="ctor" tabindex="-1">ctor <a class="header-anchor" href="#ctor" aria-label="Permalink to &quot;ctor&quot;">​</a></h5><p><code>Function</code></p><p>The constructor to register.</p><h5 id="typename" tabindex="-1">typeName <a class="header-anchor" href="#typename" aria-label="Permalink to &quot;typeName&quot;">​</a></h5><p><code>string</code></p><p>The name to register it under.</p><h4 id="returns-8" tabindex="-1">Returns <a class="header-anchor" href="#returns-8" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>void</code></p>',165)])])}const u=a(n,[["render",i]]);export{p as __pageData,u as default};
